defaults:
[cost]
internal_envs = ["ci", "dev", "test", "staging"]

[[cost.rule]]
match = { tag = { product = "*", env = "*" } }
set = { product = "{tag.product}", env = "{tag.env}" }

[[cost.rule]]
match = { tag = { product = "*" } }
set = { product = "{tag.product}" }

[[cost.report]]
name = "prod-weekly"
scope = { env = "prod" }
period = "week"
schedule = "0 8 * * 1"
